INSERT INTO users (id, email, display_name, role, is_active, password_hash, organization_id) VALUES ('b2000001-0000-4000-8000-000000000028', 'retail01@example.dk', 'Retail Alliance Agent 1', 'agent', TRUE, '$2b$12$Ss7R94HhRfq3Vq22M9ivS.1/OlQMmAdxdh9x9XaTwh9F0FmR1vlZC', (SELECT id FROM organizations WHERE name = 'Retail Alliance')) ON CONFLICT (email) DO UPDATE SET display_name = EXCLUDED.display_name, organization_id = EXCLUDED.organization_id, password_hash = EXCLUDED.password_hash;
INSERT INTO team_members (team_id, user_id, joined_at) SELECT t.id, 'b2000001-0000-4000-8000-000000000028'::uuid, NOW() FROM teams t WHERE t.name = 'Retail Alliance' ON CONFLICT DO NOTHING;
